-- ============================================================
-- ClickTake Technologies — Supabase Setup Script
-- Paste this entire file into: Supabase Dashboard → SQL Editor
--   → New Query → paste → Run
-- Creates all 28 tables + seeds all data (idempotent).
-- ============================================================

-- Enable statement timeout extension for long-running seed
SET statement_timeout = '120s';

-- ============================================
-- 1. CREATE ALL TABLES (28 tables)
-- ============================================
CREATE TABLE IF NOT EXISTS "User" (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT, password TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'admin', permissions TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "Page" (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'custom', status TEXT NOT NULL DEFAULT 'published', hero TEXT, overview TEXT, body TEXT, "metaTitle" TEXT, "metaDescription" TEXT, keywords TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "BlogPost" (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'General', excerpt TEXT NOT NULL, body TEXT, status TEXT NOT NULL DEFAULT 'published', "readTime" TEXT NOT NULL DEFAULT '5 min', "metaTitle" TEXT, "metaDescription" TEXT, keywords TEXT, "publishedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "PricingTier" (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, tagline TEXT NOT NULL, audience TEXT NOT NULL, price TEXT NOT NULL, cadence TEXT NOT NULL, popular BOOLEAN NOT NULL DEFAULT false, features TEXT NOT NULL, "notIncluded" TEXT, cta TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'published', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "ContactQuery" (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT, company TEXT, need TEXT, message TEXT, source TEXT NOT NULL DEFAULT 'contact', status TEXT NOT NULL DEFAULT 'new', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "JobApplication" (id TEXT PRIMARY KEY, "jobId" TEXT NOT NULL, "positionType" TEXT, "fullName" TEXT NOT NULL, email TEXT NOT NULL, mobile TEXT, "filesFolder" TEXT, "filesManifest" TEXT, status TEXT NOT NULL DEFAULT 'new', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "SeoAudit" (id TEXT PRIMARY KEY, url TEXT NOT NULL, score INTEGER NOT NULL DEFAULT 0, "titleLen" INTEGER NOT NULL DEFAULT 0, "descLen" INTEGER NOT NULL DEFAULT 0, "h1Count" INTEGER NOT NULL DEFAULT 0, "hasCanonical" BOOLEAN NOT NULL DEFAULT false, "hasOg" BOOLEAN NOT NULL DEFAULT false, "hasJsonLd" BOOLEAN NOT NULL DEFAULT false, "hasSitemap" BOOLEAN NOT NULL DEFAULT false, "hasRobots" BOOLEAN NOT NULL DEFAULT false, issues TEXT, notes TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "MediaAsset" (id TEXT PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL DEFAULT 0, alt TEXT, folder TEXT NOT NULL DEFAULT 'uploads', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Redirect" (id TEXT PRIMARY KEY, "from" TEXT NOT NULL UNIQUE, "to" TEXT NOT NULL, status INTEGER NOT NULL DEFAULT 301, active BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "SiteSetting" (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, value TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'general', "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "ActivityLog" (id TEXT PRIMARY KEY, action TEXT NOT NULL, entity TEXT NOT NULL, "entityId" TEXT, summary TEXT NOT NULL, actor TEXT NOT NULL DEFAULT 'admin', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Lead" (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT, company TEXT, source TEXT NOT NULL DEFAULT 'website', stage TEXT NOT NULL DEFAULT 'new', value TEXT, notes TEXT, tags TEXT, owner TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "EmailTemplate" (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, subject TEXT NOT NULL, body TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'transactional', status TEXT NOT NULL DEFAULT 'draft', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "Experiment" (id TEXT PRIMARY KEY, name TEXT NOT NULL, hypothesis TEXT NOT NULL, page TEXT NOT NULL, "variantA" TEXT NOT NULL, "variantB" TEXT NOT NULL, metric TEXT NOT NULL DEFAULT 'conversion', status TEXT NOT NULL DEFAULT 'draft', "visitorsA" INTEGER NOT NULL DEFAULT 0, "visitorsB" INTEGER NOT NULL DEFAULT 0, "convA" INTEGER NOT NULL DEFAULT 0, "convB" INTEGER NOT NULL DEFAULT 0, winner TEXT, "startDate" TIMESTAMP(3), "endDate" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "ThemeVariable" (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, value TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'color', "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "TypographyPreset" (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, "fontFamily" TEXT NOT NULL, "headingScale" TEXT NOT NULL, "bodySize" TEXT NOT NULL, "lineHeight" TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "SecurityLog" (id TEXT PRIMARY KEY, type TEXT NOT NULL, ip TEXT, email TEXT, detail TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "SiteVisit" (id TEXT PRIMARY KEY, path TEXT NOT NULL, referrer TEXT, country TEXT, device TEXT NOT NULL DEFAULT 'desktop', browser TEXT, "sessionId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "TeamMember" (id TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL, department TEXT NOT NULL, bio TEXT, photo TEXT, linkedin TEXT, twitter TEXT, "order" INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "Job" (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, department TEXT NOT NULL, location TEXT NOT NULL, type TEXT NOT NULL DEFAULT 'Full-time', description TEXT NOT NULL, requirements TEXT, salary TEXT, active BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "Keyword" (id TEXT PRIMARY KEY, keyword TEXT NOT NULL UNIQUE, type TEXT NOT NULL DEFAULT 'commercial', volume INTEGER NOT NULL DEFAULT 0, difficulty INTEGER NOT NULL DEFAULT 0, cpc TEXT, intent TEXT, status TEXT NOT NULL DEFAULT 'tracking', "currentRank" INTEGER, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "Ranking" (id TEXT PRIMARY KEY, keyword TEXT NOT NULL, position INTEGER NOT NULL, engine TEXT NOT NULL DEFAULT 'google', "serpFeature" TEXT, url TEXT, date TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "AiMention" (id TEXT PRIMARY KEY, prompt TEXT NOT NULL, platform TEXT NOT NULL, mentioned BOOLEAN NOT NULL DEFAULT false, sentiment TEXT, citation TEXT, response TEXT, date TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Backlink" (id TEXT PRIMARY KEY, "sourceUrl" TEXT NOT NULL, "targetUrl" TEXT NOT NULL, "anchorText" TEXT, "domainRating" INTEGER NOT NULL DEFAULT 0, dofollow BOOLEAN NOT NULL DEFAULT true, status TEXT NOT NULL DEFAULT 'active', "firstSeen" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastSeen" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "ContentBrief" (id TEXT PRIMARY KEY, title TEXT NOT NULL, keyword TEXT NOT NULL, headings TEXT, faqs TEXT, entities TEXT, "wordCount" INTEGER NOT NULL DEFAULT 0, "seoScore" INTEGER NOT NULL DEFAULT 0, "aeoScore" INTEGER NOT NULL DEFAULT 0, "geoScore" INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'draft', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "SeoIssue" (id TEXT PRIMARY KEY, type TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'warning', url TEXT NOT NULL, detail TEXT NOT NULL, "fixSuggestion" TEXT, status TEXT NOT NULL DEFAULT 'open', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "SeoReport" (id TEXT PRIMARY KEY, type TEXT NOT NULL, score INTEGER NOT NULL DEFAULT 0, summary TEXT, data TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "ClientLogo" (id TEXT PRIMARY KEY, name TEXT NOT NULL, logo TEXT NOT NULL, website TEXT, category TEXT NOT NULL DEFAULT 'general', "order" INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Post" (id TEXT PRIMARY KEY, title TEXT NOT NULL, content TEXT, published BOOLEAN NOT NULL DEFAULT false, "authorId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);

-- ============================================
-- 2. CREATE INDEXES
-- ============================================
CREATE INDEX IF NOT EXISTS Page_status_idx ON "Page" ("status");
CREATE INDEX IF NOT EXISTS Page_category_idx ON "Page" ("category");
CREATE INDEX IF NOT EXISTS BlogPost_status_idx ON "BlogPost" ("status");
CREATE INDEX IF NOT EXISTS BlogPost_category_idx ON "BlogPost" ("category");
CREATE INDEX IF NOT EXISTS ContactQuery_status_idx ON "ContactQuery" ("status");
CREATE INDEX IF NOT EXISTS ContactQuery_source_idx ON "ContactQuery" ("source");
CREATE INDEX IF NOT EXISTS JobApplication_status_idx ON "JobApplication" ("status");
CREATE INDEX IF NOT EXISTS JobApplication_jobId_idx ON "JobApplication" ("jobId");
CREATE INDEX IF NOT EXISTS MediaAsset_folder_idx ON "MediaAsset" ("folder");
CREATE INDEX IF NOT EXISTS MediaAsset_mime_idx ON "MediaAsset" ("mime");
CREATE INDEX IF NOT EXISTS ActivityLog_entity_idx ON "ActivityLog" ("entity");
CREATE INDEX IF NOT EXISTS ActivityLog_action_idx ON "ActivityLog" ("action");
CREATE INDEX IF NOT EXISTS ActivityLog_createdAt_idx ON "ActivityLog" ("createdAt");
CREATE INDEX IF NOT EXISTS Lead_stage_idx ON "Lead" ("stage");
CREATE INDEX IF NOT EXISTS Lead_source_idx ON "Lead" ("source");
CREATE INDEX IF NOT EXISTS Lead_owner_idx ON "Lead" ("owner");
CREATE INDEX IF NOT EXISTS EmailTemplate_category_idx ON "EmailTemplate" ("category");
CREATE INDEX IF NOT EXISTS EmailTemplate_status_idx ON "EmailTemplate" ("status");
CREATE INDEX IF NOT EXISTS Experiment_status_idx ON "Experiment" ("status");
CREATE INDEX IF NOT EXISTS SecurityLog_type_idx ON "SecurityLog" ("type");
CREATE INDEX IF NOT EXISTS SecurityLog_createdAt_idx ON "SecurityLog" ("createdAt");
CREATE INDEX IF NOT EXISTS SiteVisit_path_idx ON "SiteVisit" ("path");
CREATE INDEX IF NOT EXISTS SiteVisit_createdAt_idx ON "SiteVisit" ("createdAt");
CREATE INDEX IF NOT EXISTS SiteVisit_sessionId_idx ON "SiteVisit" ("sessionId");
CREATE INDEX IF NOT EXISTS TeamMember_active_idx ON "TeamMember" ("active");
CREATE INDEX IF NOT EXISTS TeamMember_department_idx ON "TeamMember" ("department");
CREATE INDEX IF NOT EXISTS Job_active_idx ON "Job" ("active");
CREATE INDEX IF NOT EXISTS Job_department_idx ON "Job" ("department");
CREATE INDEX IF NOT EXISTS Keyword_status_idx ON "Keyword" ("status");
CREATE INDEX IF NOT EXISTS Keyword_type_idx ON "Keyword" ("type");
CREATE INDEX IF NOT EXISTS Ranking_keyword_idx ON "Ranking" ("keyword");
CREATE INDEX IF NOT EXISTS Ranking_date_idx ON "Ranking" ("date");
CREATE INDEX IF NOT EXISTS AiMention_platform_idx ON "AiMention" ("platform");
CREATE INDEX IF NOT EXISTS AiMention_date_idx ON "AiMention" ("date");
CREATE INDEX IF NOT EXISTS Backlink_status_idx ON "Backlink" ("status");
CREATE INDEX IF NOT EXISTS ContentBrief_status_idx ON "ContentBrief" ("status");
CREATE INDEX IF NOT EXISTS SeoIssue_status_idx ON "SeoIssue" ("status");
CREATE INDEX IF NOT EXISTS SeoIssue_severity_idx ON "SeoIssue" ("severity");
CREATE INDEX IF NOT EXISTS SeoReport_type_idx ON "SeoReport" ("type");
CREATE INDEX IF NOT EXISTS ClientLogo_active_idx ON "ClientLogo" ("active");
CREATE INDEX IF NOT EXISTS ClientLogo_category_idx ON "ClientLogo" ("category");

