INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-ppc-paid-ads', 'ppc-paid-ads', 'PPC / Paid Ads', 'Digital Marketing', 'published', 'PPC / Paid Ads', 'We run profitable paid media across Google, Meta, LinkedIn and TikTok, built around a CPA target you set — not vanity clicks. Daily budget pacing, creative testing and landing-page CRO are baked in, with full-funnel GA4 and server-side tracking. You keep the ad accounts; we keep the spend working.', 'Google, Meta, LinkedIn & TikTok ad campaigns engineered around profitable CPA, not clicks. Full-funnel tracking from impression to revenue.', 'PPC Management Services | ClickTake', 'PPC management services across Google, Meta, LinkedIn and TikTok — engineered around profitable CPA. Book a free audit today.', 'PPC management services, Google Ads management, Meta Ads management, paid media agency, PPC advertising services, Google Ads agency', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-content-strategy-seo', 'content-strategy-seo', 'Content Strategy & SEO', 'Digital Marketing', 'published', 'Content Strategy & SEO', 'We build topical authority, not blog posts — content clusters mapped to commercial intent and an editorial calendar your team can actually ship. Every brief targets a primary keyword with clear intent, internal links to your money pages, and a measurable SERP position to win.', 'Topical authority maps, content clusters, and editorial calendars that compound organic traffic month over month.', 'Content Strategy Services | ClickTake', 'Content strategy services that build topical authority: content clusters, editorial calendars and on-page SEO. Book a free content audit.', 'content strategy services, topical authority SEO, content clusters, editorial calendar services, SEO content marketing, content marketing agency', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-conversion-rate-optimization', 'conversion-rate-optimization', 'Conversion Rate Optimization', 'Digital Marketing', 'published', 'Conversion Rate Optimization', 'We diagnose why visitors don''t convert and ship tests that move revenue — typically a 25-60% CVR lift within 90 days. Our playbook pairs session replay, funnel analysis and A/B testing on high-traffic pages, so every experiment is measurable. You get a prioritised roadmap, shipped tests and a learnings library.', 'A/B testing, heatmaps, and funnel analysis that lift checkout conversion by 25–60% without extra ad spend.', 'Conversion Rate Optimization Services', 'Conversion rate optimization services: A/B testing, heatmaps and funnel analysis that lift CVR 25-60%. Free CRO audit — book today.', 'conversion rate optimization services, CRO agency, A/B testing services, funnel analysis, heatmap analysis, landing page optimization', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-seo-services', 'seo-services', 'SEO Services', 'Digital Marketing', 'published', 'SEO Services', 'We run technical, on-page and off-page SEO as one system, not three disconnected workstreams. Crawlability, schema, internal links, content and backlinks compound toward defensible rankings. Local businesses get a top-3 Maps pack strategy; SaaS and ecommerce get programmatic SEO.', 'Technical, on-page, and off-page SEO. We move you into the top 3 of the local pack and keep you there.', 'SEO Services | Technical, On-Page & Local', 'SEO services covering technical, on-page and off-page SEO — built to land you in the top 3 local pack. Free SEO audit, book today.', 'SEO services, technical SEO audit, on-page SEO, off-page SEO services, local SEO services, SEO agency', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-social-media-marketing', 'social-media-marketing', 'Social Media Marketing', 'Digital Marketing', 'published', 'Social Media Marketing', 'We run organic, paid, community and influencer as one engine, not four contractors. Organic builds reach, paid converts it, community turns customers into advocates, and influencer ops scale distribution. Every post has a commercial goal and every channel a defined funnel role.', 'Organic and paid social strategy that turns followers into a community and views into sales.', 'Social Media Marketing Services | ClickTake', 'Social media marketing services: organic content, paid social, community and influencer ops. Free strategy call — book today.', 'social media marketing services, social media management, paid social advertising, influencer marketing services, community management, social media agency', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-seo-web-design-services', 'seo-web-design-services', 'SEO & Web Design Services', 'Digital Marketing', 'published', 'SEO & Web Design Services', 'We design websites that rank before they look pretty — PageSpeed 90+, full schema, clean crawl paths and zero render-blocking resources. Every page is indexable, every image optimised, every internal link mapped to commercial intent. You get a site that converts search visitors.', 'Sites built SEO-first from the ground up — fast, indexable, and structured for ranking from launch day.', 'SEO Web Design Services | ClickTake', 'SEO web design services: PageSpeed 90+, schema, indexability and SEO-first builds. Free technical design audit — book today.', 'SEO web design services, SEO-friendly websites, PageSpeed optimisation, schema markup, indexable web design, SEO-first web development', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-full-stack-web-development', 'full-stack-web-development', 'Full-Stack Web Development', 'Web & Software', 'published', 'Full-Stack Web Development', 'We ship production web apps on Next.js 16, TypeScript, Prisma and Postgres, with Playwright E2E tests guarding every release. Type-safe APIs, server actions, optimistic UI, queued jobs and a real CI/CD pipeline. You get a codebase your team can own, not a black-box handover.', 'Next.js 16 + TypeScript + Prisma + Postgres. Design systems, Storybook, Playwright E2E, and CI/CD from day one.', 'Full-Stack Web Development Services', 'Full-stack web development with Next.js 16, TypeScript, Prisma, Postgres and Playwright E2E. Free architecture review — book today.', 'full-stack web development services, Next.js development agency, TypeScript web development, Prisma Postgres development, Playwright E2E testing, web application development', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-saas-platform-engineering', 'saas-platform-engineering', 'SaaS Platform Engineering', 'Web & Software', 'published', 'SaaS Platform Engineering', 'We engineer SaaS platforms that scale from 10 to 10,000 tenants without rewrites — multi-tenant isolation, Stripe billing with usage metering, RBAC, and a daily-shipping release pipeline. Auth, billing, audit logs and observability are designed in from day one, not bolted on later.', 'Multi-tenant SaaS with billing (Stripe), RBAC, audit logs, and usage metering — architected to scale to 100K tenants.', 'SaaS Platform Engineering Services', 'SaaS platform engineering: multi-tenant architecture, Stripe billing, RBAC and usage metering. Free architecture review — book today.', 'SaaS platform engineering services, multi-tenant SaaS development, Stripe billing integration, RBAC implementation, usage metering, SaaS backend engineering', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-auth-identity', 'auth-identity', 'Auth & Identity', 'Web & Software', 'published', 'Auth & Identity', 'We build authentication that doesn''t get your users phished — NextAuth, OAuth/SAML SSO for enterprise, passkeys for passwordless, and zero-trust session management. MFA, device pairing, step-up auth and audit logs are designed in. You get a system your CISO can defend.', 'NextAuth, OAuth, SSO, SAML, and passkey-based authentication with zero-trust session handling.', 'Authentication & Identity Services', 'Authentication & identity services: NextAuth, OAuth/SAML SSO, passkeys and zero-trust sessions. Free security review — book today.', 'authentication & identity services, NextAuth development, OAuth SSO integration, SAML SSO services, passkey implementation, zero-trust session management', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-python-backend-apis', 'python-backend-apis', 'Python Backend & APIs', 'Web & Software', 'published', 'Python Backend & APIs', 'We build Python backends that hold a p99 of 120ms under load — FastAPI for async requests, Celery or RQ workers for background jobs, REST or GraphQL with OpenAPI for clients, and proper connection pooling so the DB isn''t the bottleneck. Typed with Pydantic, tested with pytest, observable with OpenTelemetry.', 'FastAPI services, async workers, and typed REST/GraphQL APIs with OpenAPI docs and p99 120ms SLAs.', 'Python Backend & API Development', 'Python backend & API development with FastAPI, async workers, GraphQL and OpenAPI at p99 120ms. Free architecture review — book today.', 'Python backend & API development, FastAPI development, async Python workers, GraphQL API development, OpenAPI documentation, high-performance Python APIs', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-wordpress-web-design-services', 'wordpress-web-design-services', 'WordPress Web Design Services', 'Web & Software', 'published', 'WordPress Web Design Services', 'We build WordPress sites that don''t slow you down — WooCommerce, ACF blocks, headless WP and Lighthouse 90+. Custom themes, custom blocks, an editing experience your team can use. No page-builder bloat and no plugins we''d be embarrassed to defend in a security review.', 'Custom WordPress + WooCommerce builds with headless options, ACF blocks, and Lighthouse 90+ performance.', 'WordPress Web Design Services | ClickTake', 'WordPress web design services: WooCommerce, ACF, headless WP and Lighthouse 90+. Free site audit — book today.', 'WordPress web design services, WooCommerce development, headless WordPress, ACF block development, WordPress SEO, Lighthouse optimisation', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-ecommerce-web-design-services', 'ecommerce-web-design-services', 'Ecommerce Web Design Services', 'Web & Software', 'published', 'Ecommerce Web Design Services', 'We build ecommerce stores that load in 1.5s and convert 25-60% better — headless Shopify, Medusa or Next.js storefronts, Stripe checkout, CRO baked in. No theme bloat, no plugin soup, no checkout that loses carts. You get a store that''s fast, indexed and measurable.', 'Headless Shopify, Medusa, and custom commerce — sub-second LCP, +25–60% CVR, and infinite scale.', 'Ecommerce Web Design Services | ClickTake', 'Ecommerce web design services: headless Shopify/Medusa, Stripe, 1.5s LCP and +25-60% CVR. Free store audit — book today.', 'ecommerce web design services, headless Shopify development, Medusa commerce, Stripe ecommerce integration, Shopify Plus development, ecommerce CRO', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-custom-llm-solutions', 'custom-llm-solutions', 'Custom LLM Solutions', 'AI & Automation', 'published', 'Custom LLM Solutions', 'We build LLM systems that ship to production — RAG over your real data, fine-tuning where it earns its keep, eval harnesses for regressions, guardrails for safe outputs, and cost controls. You get measured accuracy, a fallback chain and a runbook for misbehaviour.', 'Fine-tuned and RAG-grounded LLMs over your private data — with eval harnesses, guardrails, and cost controls.', 'Custom LLM Solutions | ClickTake', 'Custom LLM solutions: RAG, fine-tuning, eval harness, guardrails and cost control. Free architecture review — book today.', 'custom LLM solutions, RAG development, LLM fine-tuning services, LLM evaluation harness, AI guardrails, LLM cost optimisation', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-ai-chatbots-assistants', 'ai-chatbots-assistants', 'AI Chatbots & Assistants', 'AI & Automation', 'published', 'AI Chatbots & Assistants', 'We build chatbots that actually do things — call your APIs, query your database, escalate to a human when stuck, and remember conversations across sessions. Deployed on your site, WhatsApp, Slack or Teams. You get a bot with a defined tool surface, human fallback and full conversation logs.', 'Production chatbots with tool-use, memory, and human handoff — deployed on your site, WhatsApp, and Slack.', 'AI Chatbot Development | ClickTake', 'AI chatbot development with tool-use, memory, human handoff and multi-channel deploy (site/WhatsApp/Slack). Free scope call — book today.', 'AI chatbot development, AI assistant development, tool-using LLM agents, conversational AI, human handoff chatbots, multi-channel AI assistants', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-prompt-engineering', 'prompt-engineering', 'Prompt Engineering', 'AI & Automation', 'published', 'Prompt Engineering', 'We engineer prompts like code — versioned, tested, evaluated against labelled sets, and optimised for cost and latency. No vibes, no ''we tried a few and this felt best''. You get a prompt library with version history, an eval suite that catches regressions, and per-prompt cost targets.', 'Systematic prompt design, evaluation, and version control for reliable LLM behaviour at scale.', 'Prompt Engineering Services | ClickTake', 'Prompt engineering services: versioning, eval suites, few-shot and cost optimisation. Free prompt audit — book today.', 'prompt engineering services, prompt versioning, LLM evaluation suites, few-shot prompting, prompt optimisation, LLM cost reduction', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-computer-vision-nlp', 'computer-vision-nlp', 'Computer Vision & NLP', 'AI & Automation', 'published', 'Computer Vision & NLP', 'We build computer vision and NLP systems that work in production — OCR, object detection, document AI and text classification, trained on your data and deployable on cloud or edge. No ''we trained a model'' demos — you get measured accuracy, an eval harness and a deploy plan.', 'OCR, object detection, document intelligence, and classification models deployed to production endpoints.', 'Computer Vision & NLP Services', 'Computer vision & NLP: OCR, object detection, document AI, classification and edge deployment. Free scope call — book today.', 'computer vision & NLP services, OCR development, object detection models, document AI, text classification, edge AI deployment', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-ai-automation', 'ai-automation', 'AI Automation', 'AI & Automation', 'published', 'AI Automation', 'We automate the workflows eating your team''s week — invoicing, onboarding, lead routing, reports and support triage — with AI where it earns its keep and deterministic code elsewhere. Human-in-the-loop, monitoring on every job, kill switch included. Typically 30+ hrs/wk saved in 90 days.', 'Workflows that eliminate 30+ hours/week of manual work — connecting your tools with intelligent agents.', 'AI Automation Services | ClickTake', 'AI automation services that eliminate 30+ hrs/wk of manual work — workflow orchestration, integrations and monitoring. Free scope call — book today.', 'AI automation services, workflow automation, AI agent orchestration, human-in-the-loop automation, integration automation, business process automation', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-ai-agent-development', 'ai-agent-development', 'AI Agent Development', 'AI & Automation', 'published', 'AI Agent Development', 'We build production AI agents that plan, use tools, remember context and orchestrate with others — not single-shot LLM calls. LangGraph for stateful orchestration, structured memory, tool-use with retries, and eval suites. You get an agent that completes multi-step tasks reliably.', 'Autonomous goal-pursuing agents with planning, memory, and multi-agent orchestration via LangGraph.', 'AI Agent Development Services | ClickTake', 'AI agent development: LangGraph, planning, memory, multi-agent orchestration and production evals. Free scope call — book today.', 'AI agent development services, LangGraph development, multi-agent orchestration, agent memory systems, AI planning agents, agent evaluation', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-graphic-design', 'graphic-design', 'Graphic Design', 'Creative & Brand', 'published', 'Graphic Design', 'We design brand identities that hold up across every touchpoint — logos, type, colour, marketing collateral, social creatives and enforceable guidelines. Not a logo on a slide; a system that scales from billboard to favicon. You get formats your team can actually use.', 'Logos, brand systems, marketing collateral, and social creatives that look premium and convert.', 'Graphic Design Services | ClickTake', 'Graphic design services: brand identity, logos, marketing collateral and social creatives. Free brand audit — book today.', 'graphic design services, brand identity design, logo design services, marketing collateral design, social media creatives, brand guidelines', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-professional-web-design-services', 'professional-web-design-services', 'Professional Web Design Services', 'Creative & Brand', 'published', 'Professional Web Design Services', 'We design websites the way senior product teams do — UX research, user flows, wireframes, Figma design systems and hi-fi prototypes user-tested before code. No design by committee. You get a design system your developers can implement and marketers can extend.', 'Conversion-focused web design with UX research, wireframes, and pixel-perfect Figma handoff.', 'Professional Web Design Services | ClickTake', 'Professional web design services: UX research, wireframes, Figma design systems and hi-fi prototypes. Free UX audit — book today.', 'professional web design services, UX research services, wireframe design, Figma design systems, high-fidelity prototypes, user experience design', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-b2b-video-production', 'b2b-video-production', 'B2B Video Production', 'Creative & Brand', 'published', 'B2B Video Production', 'We produce B2B videos that earn their place in your funnel — explainers that shorten sales cycles, demos that drive trials, ad creatives that lower CPA, motion graphics that simplify. Scripted, shot and edited in every aspect ratio each platform needs. Every video has a job.', 'Explainer videos, product demos, and ad creatives — scripted, shot, and edited end-to-end.', 'B2B Video Production Services | ClickTake', 'B2B video production: explainer videos, product demos, ad creatives and motion graphics. Free creative scoping — book today.', 'B2B video production services, explainer video production, product demo videos, ad creative video, motion graphics, corporate video production', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-web-design-services', 'web-design-services', 'Web Design Services', 'Creative & Brand', 'published', 'Web Design Services', 'We design websites end-to-end — research, IA, wireframes, design systems, UI kits, dev handoff and design QA through to launch. One team owns the design from first sketch to shipped site, so what you saw in Figma is what goes live. No ''the developer didn''t quite get it right''.', 'End-to-end web design from concept to launch — design systems, UI kits, and developer handoff.', 'Web Design Services | ClickTake', 'Web design services: end-to-end design systems, UI kits, dev handoff and design QA. Free design audit — book today.', 'web design services, design systems, UI kits, design handoff, design QA, responsive web design', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-small-business-web-design-services', 'small-business-web-design-services', 'Small Business Web Design Services', 'Creative & Brand', 'published', 'Small Business Web Design Services', 'We build small business websites that launch in weeks, rank locally and your team can update without calling us — mobile-first, local-SEO ready, on a CMS your staff can run. No bloated retainers, no locked editing, no per-page invoices. You get a site that earns its keep from day one.', 'Affordable, fast-launch websites for small businesses — local-SEO-ready and conversion-optimized.', 'Small Business Web Design Services', 'Small business web design services: fast launch, local-SEO ready, mobile-first and easy CMS. Free scope call — book today.', 'small business web design services, small business website design, local SEO ready websites, easy CMS websites, fast launch websites, mobile-first small business sites', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "Page" (id, slug, title, category, status, hero, overview, body, "metaTitle", "metaDescription", keywords, "createdAt", "updatedAt") VALUES ('page-responsive-web-design-services', 'responsive-web-design-services', 'Responsive Web Design Services', 'Creative & Brand', 'published', 'Responsive Web Design Services', 'We design responsive websites that work on every device — mobile-first layouts, fluid type, zero CLS and WCAG 2.2 AA accessibility built in. Engineered against Core Web Vitals, tested with screen readers. You get a site that ranks, converts and is usable by every customer.', 'Flawless experiences across every device — mobile, tablet, desktop, and ultra-wide — with no layout shifts.', 'Responsive Web Design Services | ClickTake', 'Responsive web design services: mobile-first, fluid layouts, no CLS and WCAG 2.2 AA. Free accessibility audit — book today.', 'responsive web design services, mobile-first web design, fluid layout design, CLS-free websites, WCAG 2.2 AA accessibility, responsive web development', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "BlogPost" (id, slug, title, category, excerpt, body, status, "readTime", "createdAt", "updatedAt", "publishedAt") VALUES ('blog-blog-7-best-ai-chatbots-for-capturing-website-leads-2026', 'blog-7-best-ai-chatbots-for-capturing-website-leads-2026', '7 Best AI Chatbots for Capturing Website Leads (2026)', 'AI Automation', 'If you''re asking what is the best AI chatbot for capturing leads on a website, the answer depends on something most buying guides skip entirely: whether the bot actually qualifies prospects or merely collects their contact details.', 'If you''re asking what is the best AI chatbot for capturing leads on a website, the answer depends on something most buying guides skip entirely: whether the bot actually qualifies prospects or merely collects their contact details.', 'published', '14 min', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "BlogPost" (id, slug, title, category, excerpt, body, status, "readTime", "createdAt", "updatedAt", "publishedAt") VALUES ('blog-blog-7-social-media-content-types-that-actually-drive-sales', 'blog-7-social-media-content-types-that-actually-drive-sales', '7 social media content types that actually drive sales', 'Digital Marketing', 'Most brands measure social media performance by likes, shares, and follower growth. These metrics feel meaningful; they''re easy to report, and they generate the kind of positive momentum that keeps stakeholders happy in a monthly review.', 'Most brands measure social media performance by likes, shares, and follower growth. These metrics feel meaningful; they''re easy to report, and they generate the kind of positive momentum that keeps stakeholders happy in a monthly review.', 'published', '11 min', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "BlogPost" (id, slug, title, category, excerpt, body, status, "readTime", "createdAt", "updatedAt", "publishedAt") VALUES ('blog-blog-ai-automations-that-actually-work-for-small-businesses', 'blog-ai-automations-that-actually-work-for-small-businesses', 'AI Automations That Actually Work for Small Businesses', 'AI Automation', 'If you''re wondering what AI automations actually work for small businesses, you''re not alone — and the answer is more straightforward than most vendors make it sound.', 'If you''re wondering what AI automations actually work for small businesses, you''re not alone — and the answer is more straightforward than most vendors make it sound.', 'published', '12 min', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "BlogPost" (id, slug, title, category, excerpt, body, status, "readTime", "createdAt", "updatedAt", "publishedAt") VALUES ('blog-blog-ai-business-automation-what-actually-works-for-smes', 'blog-ai-business-automation-what-actually-works-for-smes', 'AI business automation: what actually works for SMEs', 'AI Automation', 'A practical breakdown of the AI automations that deliver real ROI for small and medium enterprises — and the ones that are smoke and mirrors.', 'A practical breakdown of the AI automations that deliver real ROI for small and medium enterprises — and the ones that are smoke and mirrors.', 'published', '13 min', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "BlogPost" (id, slug, title, category, excerpt, body, status, "readTime", "createdAt", "updatedAt", "publishedAt") VALUES ('blog-blog-how-to-build-a-social-media-content-strategy-in-2026', 'blog-how-to-build-a-social-media-content-strategy-in-2026', 'How to build a social media content strategy in 2026', 'Digital Marketing', 'A repeatable framework for building a social media content strategy that compounds — from audience research to editorial calendar to measurement.', 'A repeatable framework for building a social media content strategy that compounds — from audience research to editorial calendar to measurement.', 'published', '15 min', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO NOTHING;
