INSERT INTO "PricingTier" (id, name, tagline, audience, price, cadence, popular, features, "notIncluded", cta, status, "createdAt", "updatedAt") VALUES ('tier-starter', 'Starter', 'For new founders & local businesses', 'From £1,500', '£1,500', 'one-off project', FALSE, 'Up to 5-page mobile-first Next.js website\nGoogle Business Profile setup + optimization\nFoundational on-page SEO (titles, meta, schema, sitemap)\nContact form with spam protection + email notifications\nSSL, CDN, analytics and Search Console setup\nDomain + 1 year managed hosting\n2 rounds of revisions\n14-day post-launch support', 'AI chatbot or automation\nOngoing monthly SEO\nPaid media management', 'Start with Starter', 'published', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (name) DO NOTHING;
INSERT INTO "PricingTier" (id, name, tagline, audience, price, cadence, popular, features, "notIncluded", cta, status, "createdAt", "updatedAt") VALUES ('tier-growth', 'Growth', 'For scaling brands & e-commerce stores', 'From £6,000', '£6,000', 'one-off + monthly retainer', TRUE, 'Production-ready website or e-commerce rebuild\nHeadless commerce (Shopify / Medusa) with 1.5s LCP\nAI automation (chatbot, lead scoring, or workflow)\nOngoing monthly SEO (technical + content)\nPaid media management (Google + Meta)\nConversion rate optimization (A/B testing)\nDesign system in Storybook + Playwright E2E\nWeekly demos + 30-day post-launch hypercare', 'Multi-agent orchestration\nCustom LLM fine-tuning', 'Start with Growth', 'published', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (name) DO NOTHING;
INSERT INTO "PricingTier" (id, name, tagline, audience, price, cadence, popular, features, "notIncluded", cta, status, "createdAt", "updatedAt") VALUES ('tier-scale', 'Scale', 'For SaaS platforms & enterprises', 'From £18,000', '£18,000', 'one-off + monthly retainer', FALSE, 'Multi-tenant SaaS platform engineering\nCustom AI / multi-agent orchestration (LangGraph)\nCloud DevOps (AWS/GCP/Azure) with Terraform IaC\nKubernetes autoscaling + observability stack\nSOC 2 Type II audit prep + security hardening\nDedicated lead engineer + 4-person pod\np99 120ms SLA + 99.9% uptime guarantee\n24/7 on-call runbook + quarterly roadmapping', '', 'Start with Scale', 'published', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (name) DO NOTHING;
INSERT INTO "PricingTier" (id, name, tagline, audience, price, cadence, popular, features, "notIncluded", cta, status, "createdAt", "updatedAt") VALUES ('tier-custom-quote', 'Custom Quote', 'For something that doesn''t fit a box', 'Let''s scope it', 'Custom', 'scoped in a free 30-min call', FALSE, 'Fixed-scope, fixed-fee PoC in 6 weeks\nSenior engineer (not salesperson) on the call\nDraft architecture + ballpark estimate\nPick any mix of the 24 services\nNo long-term contract required to start\nNDA signed before any discovery call\nUK Ltd Co + GDPR-compliant invoicing\nCode + keys handed over, never locked in', '', 'Book a discovery call', 'published', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (name) DO NOTHING;
